actions.script:
const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(L('This import is not available; start again from the file')); return }
const personal = asPersonal !== 'N'
const admin = ec.user.isInGroup('BOSS_CONTACT_ADMIN') || ec.user.isInGroup('ADMIN')
if (!personal && !admin) { ec.message.addValidationError(null, 'asPersonal', null, L('Only contact admins import into the directory'), null); return }
if (!['skip', 'update', 'create'].includes(duplicatePolicy)) { ec.message.addValidationError(null, 'duplicatePolicy', null, L('Choose what to do with duplicates'), null); return }
const books = ec.service.sync().name('mantle.party.ContactBookServices.get#UserContactBooks').call()?.contactBookList || []
const book = contactBookId ? books.find((entry) => entry.contactBookId === contactBookId) : null
if (contactBookId && (book == null || !['CbpEdit', 'CbpManage'].includes(book.permissionEnumId))) {
    ec.message.addValidationError(null, 'contactBookId', null, L('Choose a book you may add to'), null); return }
if (personal && book && !book.isOwner) { ec.message.addValidationError(null, 'contactBookId', null, L('Personal contacts go in one of your own books'), null); return }
const groupIds = (contactBookGroupIdList == null ? [] : (typeof contactBookGroupIdList === 'string' ? contactBookGroupIdList.split(',') : Array.from(contactBookGroupIdList)))
        .map((id) => String(id).trim()).filter((id) => id && book && (book.groupList || []).some((group) => group.contactBookGroupId === id))
if (!personal && !book && (groupIds.length || groupNames)) { ec.message.addValidationError(null, 'contactBookId', null, L('Groups need a book'), null); return }
ec.service.sync().name('ironstone.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'options', options: {
    asPersonal: personal, contactBookId: contactBookId || null, contactBookGroupIdList: groupIds,
    groupNames: groupNames ? String(groupNames).trim() : null, duplicatePolicy: duplicatePolicy, useFileGroups: useFileGroups !== 'N'}}}).call()

const L = (text) => ec.l10n.localize(text)
const books = Array.from(booksOut.contactBookList || []).filter((book) => ['CbpEdit', 'CbpManage'].includes(book.permissionEnumId))
isContactAdmin = ec.user.isInGroup('BOSS_CONTACT_ADMIN') || ec.user.isInGroup('ADMIN')
bookOptions = books.map((book) => ({key: book.contactBookId, text: book.contactBookName + (book.isOwner ? ' · ' + L('yours') : ' · ' + L('shared'))}))
const defaultBook = books.find((book) => book.isOwner && book.isDefault) || books.find((book) => book.isOwner)
const saved = draft.options || {}
options = {importId: importId, asPersonal: saved.asPersonal === false ? 'N' : 'Y', contactBookId: saved.contactBookId || (defaultBook ? defaultBook.contactBookId : null),
    contactBookGroupIdList: saved.contactBookGroupIdList || [], groupNames: saved.groupNames || '', duplicatePolicy: saved.duplicatePolicy || 'skip',
    useFileGroups: saved.useFileGroups === false ? 'N' : 'Y'}
